insert into public.instructors (slug, sort, name, role, photo_id, photo_alt, qualification, seasons, languages, bio, courses, legs, sample) values
  ('andrei', 1, 'Andrei K.', 'Lead instructor', '1792970826349-0298fd592e39', 'Portrait of a sailing instructor at the helm in evening light', 'IYT Yachtmaster Offshore, instructor', 15, array['en','ru']::text[], 'Calm, patient and very particular about fenders. His rule: you touch every line and every control yourself, and nobody finishes the week without mooring the boat at least ten times.', array['bareboat-skipper','yachtmaster-coastal','yachtmaster-offshore']::text[], '{}'::text[], true),
  ('helen', 2, 'Helen M.', 'Instructor', '1791802250702-773abb82127e', 'Portrait of a sailing instructor in a blue cap by the harbour', 'IYT Yachtmaster Ocean, instructor', 22, array['en','de']::text[], 'Learned to navigate with a sextant long before GPS was common and still carries one. Teaches celestial navigation and the radio course, and makes chartwork feel like a puzzle rather than homework.', array['yachtmaster-ocean','yachtmaster-offshore','vhf-radio-operator']::text[], '{}'::text[], true),
  ('deniz', 3, 'Deniz A.', 'Instructor', '1561983173-3e88f6125580', 'Portrait of a young sailing instructor on deck', 'IYT Bareboat Skipper, instructor', 6, array['en','tr']::text[], 'Grew up racing dinghies in Fethiye bay. Good with first-timers: plenty of practice, short explanations and a joke when the fenders end up in the wrong place.', array['introduction-to-yachting','international-flotilla-skipper','bareboat-skipper']::text[], '{}'::text[], true),
  ('mei', 4, 'Mei L.', 'Instructor', '1569078449082-d264d9e239c5', 'Portrait of a smiling sailing instructor in a bucket hat', 'IYT Yachtmaster Coastal, VHF instructor', 8, array['en','es']::text[], 'Runs the radio course and the ICC assessments. A former delivery skipper in the western Mediterranean, she believes a good briefing prevents most problems on board.', array['vhf-radio-operator','introduction-to-yachting','icc']::text[], '{}'::text[], true),
  ('nikolai', 5, 'Nikolai Shilin', 'Skipper', '/people/nikolai.webp', 'Nikolai Shilin at the helm of a sailing yacht', 'IYT Bareboat Skipper', 5, array['en','ru']::text[], 'Skippers our Aegean passages, from Fethiye to Bodrum and Kuşadası and on to Istanbul. He also writes the theory articles on this site, so what you read here is what you practise on board.', '{}'::text[], array['fethiye-bodrum','fethiye-kusadasi','kusadasi-istanbul']::text[], false),
  ('mehmet', 6, 'Mehmet Y.', 'Skipper', '1674487846026-7f393d850c17', 'Portrait of a skipper in a knitted hat at the helm station', 'IYT Yachtmaster Offshore', 25, array['tr','en']::text[], 'Has sailed the Lycian coast and the crossing to Cyprus more times than he can count, and knows every bay where you can sit out a blow.', '{}'::text[], array['fethiye-cyprus','finike-cyprus','fethiye-kemer']::text[], true),
  ('pablo', 7, 'Pablo R.', 'Skipper', '1543003743-993c0632996e', 'Portrait of a bearded skipper on a yacht at sunset', 'IYT Yachtmaster Offshore', 9, array['es','en']::text[], 'Delivers yachts between Turkey and the western Mediterranean in winter. On passage he runs a proper watch system and loves a landfall at night.', '{}'::text[], array['kusadasi-istanbul','fethiye-kusadasi']::text[], true),
  ('anna', 8, 'Anna S.', 'Skipper', '1595586470928-b68f7251026f', 'Portrait of a smiling skipper on a sailing yacht', 'IYT Yachtmaster Coastal', 7, array['en','ru','de']::text[], 'Started as crew on our passages and now skippers them. Keeps the pace relaxed early in the week and saves the long legs for when the crew is ready.', '{}'::text[], array['fethiye-bodrum','fethiye-kekova','fethiye-kusadasi']::text[], true)
