-- Instructors and skippers (generated from content/instructors.json). sample = true marks placeholder profiles; replace them with real people.
on conflict (slug) do update set sort = excluded.sort, name = excluded.name, role = excluded.role, photo_id = excluded.photo_id, photo_alt = excluded.photo_alt, qualification = excluded.qualification, seasons = excluded.seasons, languages = excluded.languages, bio = excluded.bio, courses = excluded.courses, legs = excluded.legs, sample = excluded.sample;
